package com.northstarbank.entitlements;import java.time.LocalDate;import org.springframework.boot.*;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component class DelegationJobs{private final EntitlementService service;DelegationJobs(EntitlementService s){service=s;}@Scheduled(cron="0 5 0 * * *",zone="Europe/London")void daily(){service.advance(LocalDate.now());}@Bean ApplicationRunner asOfRunner(){return args->{if(args.containsOption("as-of-date"))service.advance(LocalDate.parse(args.getOptionValues("as-of-date").getFirst()));};}}
